import { writeUnformatted } from './format.ts'

// One JSON file, bundled into JBrowse Desktop's MCP server (esbuild loads it
// like the .md topics), so `docs topic:"model:X"` answers from the same run
// that wrote the website's pages and cannot drift from it. Regenerated by
// `pnpm autogen`; `--check` reports it stale like every page above.
export const AGENT_TYPE_DOCS_PATH =
  'products/jbrowse-desktop/electron/mcp/docs/typeDocs.generated.json'

export interface AgentTypePage {
  category: string
  text: string
}

export function writeAgentTypeDocs(pages: {
  models: Record<string, AgentTypePage>
  configs: Record<string, AgentTypePage>
}) {
  const sorted = (record: Record<string, AgentTypePage>) =>
    Object.fromEntries(
      Object.entries(record).sort(([a], [b]) => a.localeCompare(b)),
    )
  writeUnformatted(
    AGENT_TYPE_DOCS_PATH,
    `${JSON.stringify(
      { models: sorted(pages.models), configs: sorted(pages.configs) },
      null,
      1,
    )}\n`,
  )
}
